CREATE DATABASE IF NOT EXISTS db_pure_bloom CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_pure_bloom;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,nama_lengkap VARCHAR(100) NOT NULL,role ENUM('admin','kasir') NOT NULL DEFAULT 'kasir',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE produk(produk_id INT AUTO_INCREMENT PRIMARY KEY,kode_produk VARCHAR(30) UNIQUE NOT NULL,nama_produk VARCHAR(120) NOT NULL,harga_beli DECIMAL(12,2) NOT NULL DEFAULT 0,harga_jual DECIMAL(12,2) NOT NULL DEFAULT 0,stok INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pelanggan(pelanggan_id INT AUTO_INCREMENT PRIMARY KEY,nama_pelanggan VARCHAR(120) NOT NULL,nomor_telepon VARCHAR(30),alamat TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE penjualan(penjualan_id INT AUTO_INCREMENT PRIMARY KEY,tanggal_penjualan DATETIME DEFAULT CURRENT_TIMESTAMP,pelanggan_id INT NULL,user_id INT NOT NULL,total_harga DECIMAL(12,2) NOT NULL DEFAULT 0,uang_bayar DECIMAL(12,2) NOT NULL DEFAULT 0,kembalian DECIMAL(12,2) NOT NULL DEFAULT 0,FOREIGN KEY(pelanggan_id) REFERENCES pelanggan(pelanggan_id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE RESTRICT);
CREATE TABLE detail_penjualan(detail_id INT AUTO_INCREMENT PRIMARY KEY,penjualan_id INT NOT NULL,produk_id INT NOT NULL,jumlah_produk INT NOT NULL,harga_satuan DECIMAL(12,2) NOT NULL,subtotal DECIMAL(12,2) NOT NULL,FOREIGN KEY(penjualan_id) REFERENCES penjualan(penjualan_id) ON DELETE CASCADE,FOREIGN KEY(produk_id) REFERENCES produk(produk_id) ON DELETE RESTRICT);
